#define CACHE_LINE_SIZE 64
#define N 100

// 1. Spatial Locality: Row-Major Access (C/C++ default)
int matrix[N][N];
void optimize_access() {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            matrix[i][j] += 1; // Excellent cache line utilization
        }
    }
}

// 2. Avoidance of False Sharing (Padding)
// Ensures unrelated variables accessed by different threads
// reside on separate cache lines, preventing contention.
struct AlignedCounter {
    long value;
    char pad[CACHE_LINE_SIZE - sizeof(long)];
};
AlignedCounter shared_data[4];

// 3. Cache Control Hint (Manual Pre-fetching)
// Tells the CPU to load data into the cache before needed
// (Specific intrinsic varies by compiler/ISA)
void process_with_prefetch(int* arr) {
    for (int i = 0; i < N; i++) {
        // Prefetch data needed in the next few iterations (e.g., 8 iterations ahead)
        __builtin_prefetch(&arr[i + 8], 0 /* read */, 3 /* high locality */);
        arr[i] *= 2;
    }
}
